import { z } from 'zod';
import { isAbsoluteUrl } from '../../../../isAbsoluteUrl.js';
import { normalizeRelativePath } from '../../../../transforms/normalizeRelativePath.js';
export const openapiStringSchema = z
    .string()
    .trim()
    .nonempty()
    .transform((value, ctx) => {
    if (isAbsoluteUrl(value)) {
        try {
            const url = new URL(value);
            if (url.protocol !== 'https:' && url.protocol !== 'http:') {
                ctx.addIssue({
                    code: z.ZodIssueCode.custom,
                    message: "Must use protocol https or http. Urls with 'http://' are only supported with cli option --local-schema",
                });
                return z.NEVER;
            }
        }
        catch (_a) {
            ctx.addIssue({
                code: z.ZodIssueCode.custom,
                message: 'Invalid URL',
            });
            return z.NEVER;
        }
        return value;
    }
    else {
        return normalizeRelativePath(value);
    }
});
export const openapiObjSchema = z
    .object({
    source: openapiStringSchema,
    directory: z.string().trim().optional(),
    overlays: z
        .array(openapiStringSchema)
        .optional()
        .describe('OpenAPI Overlay documents to apply to the source specification, in order. An empty array disables all overlays for this specification, including auto-discovered ones.'),
})
    .strict();
export const openApiSchema = z
    .union([
    openapiStringSchema,
    z.array(z.union([openapiStringSchema, openapiObjSchema])),
    openapiObjSchema,
])
    .describe('A string, an array of strings or objects, or an object of absolute or relative urls pointing to the OpenAPI file(s), optionally with OpenAPI Overlay documents to apply');
/** Normalizes any accepted `openapi` config shape into a flat list of entries. */
export const extractOpenApiEntries = (config) => {
    if (config == undefined)
        return [];
    if (typeof config === 'string')
        return [{ source: config }];
    if (Array.isArray(config)) {
        return config.map((entry) => typeof entry === 'string'
            ? { source: entry }
            : { source: entry.source, directory: entry.directory, overlays: entry.overlays });
    }
    return [{ source: config.source, directory: config.directory, overlays: config.overlays }];
};
